<?php ob_start(); $scanCtx=$scanCtx??(function_exists('scan_active_context')?scan_active_context():[]); $scanDisabled=($scanCtx['running']??false)&&!($scanCtx['stale']??false); ?><h1><?= e(t('Users')) ?></h1><table><tr><th><?= e(t('Name')) ?></th><th><?= e(t('Path')) ?></th><th><?= e(t('Sites')) ?></th><th><?= e(t('Findings')) ?></th><th><?= e(t('Last scan')) ?></th><th><?= e(t('Actions')) ?></th></tr><?php foreach($users as $u): ?><tr><td><?= e($u['name']) ?></td><td><code><?= e($u['base_path']) ?></code></td><td><?= e($u['sites_count']) ?></td><td><?= e($u['findings_count']) ?></td><td><?= e($u['last_scan_at']) ?></td><td><form class="scan-form" method="post" action="/scan/start"><input type="hidden" name="scope" value="user"><input type="hidden" name="value" value="<?= e($u['name']) ?>"><select class="input" name="profile"><?php foreach(['fast','standard','deep'] as $p): ?><option value="<?= e($p) ?>"><?= e(t($p)) ?></option><?php endforeach ?></select><button class="btn small" <?= $scanDisabled?'disabled':'' ?>><?= e(t('Scan this user')) ?></button><?php if($scanDisabled): ?><div class="muted"><?= e(t('Another scan is already running: Scan #:id.', ['id'=>$scanCtx['run']['id']??'pending'])) ?> <a href="/scan/active"><?= e(t('View details')) ?></a></div><?php endif ?></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
